import json
d=json.load(open('data/verification/sources/refs_online.json'))
for k in ['POK','KLN','MPP','BQT','MON','AHD','BRT','KNT','PHD','NYB','HRN','HUB','ARY','IEC','SYN','WLD','SKT']:
    v=d.get(k)
    if not v: continue
    print('==',k)
    for f in ['kind','local_file','page_offset','lookup_hint','scans']:
        if f in v: print('  ',f,':',str(v[f])[:300])
"; ls data/verification/sources/refs/ | head -80

cd /home/sfmqrb/git/rishe/data/verification/sources/refs
python3 - <<'EOF'
txt=open('BQT_v1_pages.txt',encoding='utf-8',errors='replace').read()
leaves=txt.split('\f')
# find leaf containing آلگونه
for i,L in enumerate(leaves):
    if 'آلگونه' in L:
        print('leaf',i, 'tag:', L[:120].replace('\n',' | '))
print('---- آرنج leaves')
for i,L in enumerate(leaves):
    if 'آرنج' in L and i<400:
        print('leaf',i, L[:100].replace('\n',' | '))
EOF

